def longestAlternatingPath(parent, s):
    n = len(parent)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)
    order = [0]
    for u in order:
        order.extend(children[u])
    b1 = [0] * n
    b2 = [0] * n
    best = 1
    for u in reversed(order):
        best = max(best, b1[u] + b2[u] + 1)
        p = parent[u]
        if p >= 0 and s[p] != s[u]:
            c = b1[u] + 1
            if c > b1[p]:
                b2[p] = b1[p]
                b1[p] = c
            elif c > b2[p]:
                b2[p] = c
    return best
